sys_script_include.script:
var StateChangeUtils = Class.create();
StateChangeUtils.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    // Method to move to "Work In Progress" (Value: 2)
    startWork: function() {
        var recordSysId = this.getParameter('sysparm_record_sysid');
        var tableName = this.getParameter('sysparm_table_name');
        var record = new GlideRecord(tableName);
        if (record.get(recordSysId)) {
            record.state = 2; // Set state to Work In Progress
            record.update();
            return "success_wip";
        }
        return "error";
    },

    // Method to move to "Pending" (Value: -5)
    putOnPending: function() {
        var recordSysId = this.getParameter('sysparm_record_sysid');
        var tableName = this.getParameter('sysparm_table_name');
        var workNotes = this.getParameter('sysparm_work_notes');

        var record = new GlideRecord(tableName);
        if (record.get(recordSysId)) {
            record.work_notes = workNotes; // Require work notes
            record.state = -5; // Set state to Pending
            // Add other mandatory fields for Pending state if necessary (e.g., a "Pending Reason" field)
            record.update();
            return "success_pending";
        }
        return "error";
    },

    // Method to move to "Closed Complete" (Value: 3)
    closeComplete: function() {
        var recordSysId = this.getParameter('sysparm_record_sysid');
        var tableName = this.getParameter('sysparm_table_name');
        var workNotes = this.getParameter('sysparm_work_notes');

        var record = new GlideRecord(tableName);
        if (record.get(recordSysId)) {
            record.work_notes = workNotes; 
            record.state = 3; // Set state to Closed Complete
            // Add other mandatory closure fields if necessary (e.g., 'close_code', 'close_notes')
            record.update();
            return "success_closed";
        }
        return "error";
    },

    type: 'StateChangeUtils'
});
